SELECT ?zone ?zlabel ?point ?point_uri ?point_class ?ts ?setpoint ?sp_class WHERE {
  ?zone brick:hasSubClassOf* ?zone; rdf:type brick:Zone .
  FILTER(str(?zone) LIKE "%Perimeter_bot_ZN_2%") .
  OPTIONAL { ?zone ?point_uri ?point . }
}

SELECT DISTINCT ?node ?label WHERE {
  ?node brick:hasSubClassOf* ?node .
  FILTER(str(?node) LIKE "%Perimeter_bot_ZN_2%") .
  OPTIONAL { ?node rdfs:label ?label } .
}

SELECT DISTINCT ?node ?label WHERE {
  ?node rdfs:label ?label .
  FILTER(str(?label) LIKE "%Perimeter_bot_ZN_2%") .
}

SELECT ?zone ?label WHERE {
  ?zone rdfs:label ?label .
  ?zone rdf:type brick:Zone .
} LIMIT 5

SELECT ?p ?ts ?pcls WHERE {
  ?zr rdfs:label "Perimeter_bot_ZN_2" .
  ?zr brick:hasPoint ?p .
  ?p rdf:type ?pcls .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts . }
}

